VALUES (6, 1, 'Telma 40', 'Telmisartan Tablets IP', 'Antihypertensive (ARB)', 'Glenmark Pharmaceuticals', 'Tablet', '40 mg', '[{"name": "Telmisartan IP", "strength": "40", "unit": "mg", "purpose": "Angiotensin II Receptor Antagonist"}]', '["Sodium Hydroxide", "Meglumine", "Povidone K-25", "Sorbitol", "Magnesium Stearate"]', 'Oblong', 'White to off-white', 'Single break line', 'Uncoated', 'Treatment of essential hypertension (high blood pressure) and prevention of cardiovascular events.', 'Take 1 tablet once daily at the same time each day, with or without food.', 'Contraindicated during pregnancy (teratogenic risk). Regularly monitor potassium levels.', 'Low blood pressure, back pain, dizziness, sinus congestion.', 'Store in the moisture-proof blister package below 30°C. Tablets are hygroscopic.', 'Schedule H', 'Telma 40 Telmisartan tablet for high blood pressure. Take once daily at a fixed time. Do not skip doses.', 'टेल्मा 40 हाई ब्लड प्रेशर की दवा। इसे प्रतिदिन एक निश्चित समय पर लें। खुराक न छोड़ें।', 'टेल्मा 40 उच्च रक्तदाबाची गोळी. दररोज एकाच निश्चित वेळी एक गोळी घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
