VALUES (7, 1, 'Atorva 20', 'Atorvastatin Tablets IP', 'Lipid-Lowering Agent (Statin)', 'Zydus Lifesciences', 'Tablet', '20 mg', '[{"name": "Atorvastatin Calcium Trihydrate IP eq. to Atorvastatin", "strength": "20", "unit": "mg", "purpose": "HMG-CoA Reductase Inhibitor"}]', '["Calcium Carbonate", "Lactose Monohydrate", "Microcrystalline Cellulose", "Croscarmellose Sodium", "Polysorbate 80", "Hydroxypropyl Cellulose", "Opadry White"]', 'Round biconvex', 'White', 'None', 'Film-coated', 'Hypercholesterolemia and prevention of heart attacks, stroke, and arterial blockage.', 'Take 1 tablet once daily in the evening or bedtime, with or without food.', 'Inform doctor immediately if experiencing unexplained muscle tenderness, cramps or weakness.', 'Muscle ache (myalgia), joint pain, diarrhea, elevated liver enzymes.', 'Store below 25°C. Protect from moisture and excessive heat.', 'Schedule H', 'Atorva 20 Atorvastatin tablet for cholesterol and heart protection. Take one tablet in the evening after dinner.', 'एटोरवा 20 कोलेस्ट्रॉल और हृदय स्वास्थ्य की दवा। शाम को रात के खाने के बाद लें।', 'अटोर्वा 20 कोलेस्टेरॉल कमी करणारी गोळी. संध्याकाळी जेवणानंतर घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
