INSERT INTO medicines (id, organization_id, brand_name, generic_name, category, manufacturer, dosage_form, strength, active_ingredients, inactive_excipients, tablet_shape, tablet_color, score_line, coating_type, indications, dosage_instructions, warnings_and_precautions, side_effects, storage_conditions, schedule_type, voice_summary_en, voice_summary_hi, voice_summary_mr, status)
VALUES (8, 1, 'Cetzine 10', 'Cetirizine Hydrochloride Tablets IP', 'Antihistamine (Antiallergic)', 'Dr. Reddy''s Laboratories', 'Tablet', '10 mg', '[{"name": "Cetirizine Hydrochloride IP", "strength": "10", "unit": "mg", "purpose": "Second-generation Antihistamine"}]', '["Lactose Monohydrate", "Corn Starch", "Povidone", "Magnesium Stearate", "Hypromellose", "Titanium Dioxide", "Macrogol 400"]', 'Round', 'White', 'Bisected score line', 'Film-coated', 'Allergic rhinitis, hay fever, sneezing, runny nose, watery eyes, and itchy allergic skin hives.', 'Take 1 tablet once daily, preferably at bedtime as it may induce mild drowsiness.', 'May cause sedation. Avoid driving or operating machinery after consumption.', 'Drowsiness, fatigue, dry mouth, headache.', 'Store below 30°C in a dry place.', 'Schedule H', 'Cetzine 10 milligram allergy tablet. For runny nose, sneezing, and skin allergy. Take one tablet at night before sleeping.', 'सेटज़ीन 10 मिलीग्राम एलर्जी की दवा। छींक, बहती नाक और खुजली के लिए। रात को सोने से पहले लें।', 'सेटझिन 10 ॲलर्जीची गोळी. शिंका, सर्दी आणि खाज सुटण्यासाठी. रात्री झोपताना एक गोळी घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
