INSERT INTO medicines (id, organization_id, brand_name, generic_name, category, manufacturer, dosage_form, strength, active_ingredients, inactive_excipients, tablet_shape, tablet_color, score_line, coating_type, indications, dosage_instructions, warnings_and_precautions, side_effects, storage_conditions, schedule_type, voice_summary_en, voice_summary_hi, voice_summary_mr, status)
VALUES (9, 1, 'Combiflam', 'Ibuprofen and Paracetamol Tablets IP', 'NSAID & Analgesic Combination', 'Sanofi India Limited', 'Tablet', 'Ibuprofen 400mg + Paracetamol 325mg', '[{"name": "Ibuprofen IP", "strength": "400", "unit": "mg", "purpose": "NSAID Anti-inflammatory"}, {"name": "Paracetamol IP", "strength": "325", "unit": "mg", "purpose": "Analgesic & Antipyretic"}]', '["Maize Starch", "Purified Talc", "Sodium Starch Glycolate", "Colloidal Anhydrous Silica", "Magnesium Stearate"]', 'Capsule-shaped', 'White', 'None', 'Uncoated', 'Acute muscular pain, toothache, post-surgical pain, arthritis flare-ups, and headache.', 'Take 1 tablet after a heavy meal or with milk. Do not take on an empty stomach.', 'Risk of gastric ulcers and bleeding. Avoid if history of stomach ulcers or asthma.', 'Heartburn, acidity, indigestion, nausea.', 'Store below 30°C in a cool and dry location.', 'Schedule H', 'Combiflam pain relief tablet. For severe muscle or tooth pain. Always take with food or milk, never on an empty stomach.', 'कॉम्बिफ्लाम दर्द निवारक दवा। मांसपेशियों और दांत दर्द के लिए। हमेशा खाना खाने के बाद ही लें।', 'कॉम्बीफ्लॅम वेदनाशामक गोळी. स्नायू आणि दातदुखीसाठी. नेहमी पोटभर जेवण झाल्यावरच घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
