VALUES (11, 1, 'Taxim-O 200', 'Cefixime Tablets IP', 'Cephalosporin Antibiotic (3rd Gen)', 'Alkem Laboratories', 'Tablet', '200 mg', '[{"name": "Cefixime Trihydrate IP eq. to Anhydrous Cefixime", "strength": "200", "unit": "mg", "purpose": "Cephalosporin Antibiotic"}]', '["Microcrystalline Cellulose", "Pregelatinized Starch", "Colloidal Silicon Dioxide", "Magnesium Stearate", "Titanium Dioxide"]', 'Oblong', 'White', 'Score line on both sides', 'Film-coated', 'Typhoid fever, urinary tract infections, bronchitis, tonsillitis, and middle ear infections.', '1 tablet every 12 hours with or without food for 7 to 10 days.', 'Complete the full duration prescribed by your doctor to prevent resistance.', 'Loose stools, stomach cramps, nausea, flatulence.', 'Store below 25°C in a dry place.', 'Schedule H1', 'Taxim-O 200 Cefixime antibiotic tablet. Take one tablet every 12 hours. Do not discontinue until prescribed course is finished.', 'टैक्सिम-ओ 200 एंटीबायोटिक टैबलेट। हर 12 घंटे में एक गोली लें। डॉक्टर की सलाह अनुसार कोर्स पूरा करें।', 'टॅक्सिम-ओ 200 अँटीबायोटिक गोळी. दर 12 तासांनी एक गोळी घ्या. पूर्ण दिवस औषध चालू ठेवा.', 'active')
ON CONFLICT (id) DO NOTHING;
