VALUES (13, 1, 'Ecosprin 75', 'Aspirin Gastro-resistant Tablets IP', 'Antiplatelet Agent (Blood Thinner)', 'USV Private Limited', 'Tablet', '75 mg', '[{"name": "Aspirin IP (Acetylsalicylic Acid)", "strength": "75", "unit": "mg", "purpose": "Antiplatelet / Thromboxane Inhibitor"}]', '["Starch", "Cellulose Microcrystalline", "Methacrylic Acid Copolymer", "Talc", "Triethyl Citrate"]', 'Round', 'White', 'None', 'Enteric-coated', 'Prevention of blood clots, heart attacks, recurrent strokes, and angina.', 'Take 1 tablet daily at the same time, swallowed whole with water.', 'Risk of bleeding. Inform surgeons or dentists prior to any scheduled procedures.', 'Easy bruising, prolonged bleeding from cuts, gastric irritation.', 'Store below 25°C. Protect from moisture.', 'Schedule H', 'Ecosprin 75 low-dose aspirin blood thinner. Protects heart and prevents clots. Swallow whole daily.', 'इकोस्प्रिन 75 खून पतला करने वाली एस्पिरिन दवा। दिल के दौरे से बचाव के लिए रोज एक गोली लें।', 'इकोस्प्रिन 75 रक्त पातळ ठेवणारी गोळी. हृदयविकाराच्या झटक्यापासून संरक्षणासाठी रोज एक गोळी घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
