VALUES (14, 1, 'Cifran 500', 'Ciprofloxacin Tablets IP', 'Fluoroquinolone Antibiotic', 'Sun Pharmaceutical Industries', 'Tablet', '500 mg', '[{"name": "Ciprofloxacin Hydrochloride IP eq. to Ciprofloxacin", "strength": "500", "unit": "mg", "purpose": "Broad Spectrum Fluoroquinolone"}]', '["Corn Starch", "Microcrystalline Cellulose", "Colloidal Silicon Dioxide", "Magnesium Stearate", "Hypromellose", "Titanium Dioxide"]', 'Capsule-shaped', 'White', 'Central break line', 'Film-coated', 'Severe gastrointestinal bacterial infections, joint infections, complicated urinary tract infections.', 'Take 1 tablet twice daily with plenty of water. Avoid taking with dairy products.', 'Risk of tendonitis or tendon rupture. Avoid intense athletic exertion while taking.', 'Nausea, diarrhea, tendon pain, sun sensitivity.', 'Store below 30°C. Protect from light.', 'Schedule H1', 'Cifran 500 Ciprofloxacin antibiotic. Take twice daily with lots of water. Avoid milk or antacids at the same time.', 'सिफ्रान 500 एंटीबायोटिक। दिन में दो बार भरपूर पानी के साथ लें। दूध या दही के साथ तुरंत न लें।', 'सिफ्रान 500 अँटीबायोटिक गोळी. भरपूर पाण्यासोबत दिवसातून दोन वेळा घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
