VALUES (15, 1, 'Pan-D', 'Pantoprazole and Domperidone Prolonged-Release Capsules IP', 'Antacid & Prokinetic Combination', 'Alkem Laboratories', 'Capsule', 'Pantoprazole 40mg + Domperidone 30mg', '[{"name": "Pantoprazole Sodium IP eq. to Pantoprazole", "strength": "40", "unit": "mg", "purpose": "Proton Pump Inhibitor"}, {"name": "Domperidone IP (Sustained Release)", "strength": "30", "unit": "mg", "purpose": "Prokinetic Antiemetic"}]', '["Sugar Spheres", "HPMC", "Methacrylic Acid Copolymer", "Titanium Dioxide", "Sunset Yellow FCF"]', 'Hard Gelatin Capsule', 'Yellow and White', 'None', 'Pellet filled capsule', 'Gastroesophageal reflux disease (GERD), severe nausea, acid regurgitation, and bloating.', 'Take 1 capsule once daily in the morning on an empty stomach, 1 hour before breakfast.', 'Not recommended for long term use without clinical review.', 'Dry mouth, headache, flatulence, diarrhea.', 'Store below 25°C in a dry place.', 'Schedule H', 'Pan D capsule for severe acidity and nausea. Take on an empty stomach in the morning 45 minutes before breakfast.', 'पैन डी एसिडिटी और उल्टी/मतली की कैप्सूल। सुबह खाली पेट नाश्ते से 45 मिनट पहले लें।', 'पॅन डी ॲसिडिटी आणि उलट्या थांबवणारी कॅप्सूल. सकाळी उपाशी पोटी नाश्त्याच्या आधी घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
