VALUES (43, 1, 'Thyronorm 50', 'Thyroxine Sodium Tablets IP', 'Thyroid Hormone Replacement', 'Abbott India', 'Tablet', '50 mcg', '[{"name": "Thyroxine Sodium IP", "strength": "50", "unit": "mcg", "purpose": "Thyroid Hormone"}]', '["Microcrystalline Cellulose", "Starch", "Povidone", "Magnesium Stearate", "Purified Talc"]', 'Round biconvex', 'White', 'None', 'Film-coated', 'Hypothyroidism (underactive thyroid gland).', 'Take 1 tablet every morning with water on an empty stomach, 1 hour before tea or breakfast.', 'Take only as directed by your physician or pharmacist. Keep out of reach of children.', 'Consult package leaflet for full clinical side effects list.', 'Store below 25°C. Protect from moisture.', 'Schedule H', 'Thyronorm 50, generic Thyroxine Sodium Tablets IP 50 mcg. Used for Hypothyroidism (underactive thyroid gland).. Take 1 tablet every morning with water on an empty stomach, 1 hour before tea or breakfast.', 'Thyronorm 50, जेनेरिक Thyroxine Sodium Tablets IP 50 mcg। Hypothyroidism (underactive thyroid gland).। खुराक: Take 1 tablet every morning with water on an empty stomach, 1 hour before tea or breakfast.।', 'Thyronorm 50, जेनेरिक औषध Thyroxine Sodium Tablets IP 50 mcg. Hypothyroidism (underactive thyroid gland).. डोस: Take 1 tablet every morning with water on an empty stomach, 1 hour before tea or breakfast..', 'active')
ON CONFLICT (id) DO NOTHING;
